/* @autogenerated */
import { ResourceServerRepository } from 'app/features/access/resource-server/repository/resource-server-repository.service';
import { BaseExportAction } from 'app/shared/toolkit/action/base-export-action';
import { RoleRepository } from 'app/features/access/role/repository/role-repository.service';
import { Role } from 'app/features/access/role/model/role.model';
import { ExportDefinition } from 'app/shared/toolkit/entity-export/entity-export.model';
import { take, map } from 'rxjs';
import { Component, inject } from '@angular/core';
import { ROLE_EXCEL_COLUMNS, ROLE_EXCEL_SENSITIVE } from 'app/features/access/role/model/role-excel-columns';

@Component({
  selector: 'role-view-export-action',
  standalone: false,
  templateUrl: './role-view-export-action.component.html',
})
export class RoleViewExportActionComponent extends BaseExportAction<Role> {
  protected readonly scope = 'access/role';
  protected readonly repository = inject(RoleRepository);
  private readonly resourceServerRepository = inject(ResourceServerRepository);

  readonly definition: ExportDefinition<Role> = {
    name: 'access.role',
    scope: this.scope,
    // Las mismas columnas que la importación: el fichero se puede editar y volver a subir
    columns: ROLE_EXCEL_COLUMNS,
    sensitive: ROLE_EXCEL_SENSITIVE,
    references: {
      resourceServer: {
        names: (refs) =>
          this.resourceServerRepository.values({ uids: refs, limit: refs.length }).pipe(
            take(1),
            map((found) => Object.fromEntries(found.map((one) => [one.uid, String(one.code ?? '')]))),
          ),
      },
    },
    source: {
      acl: () => this.repository.checkAcl(),
      list: (filter) => this.repository.list(filter).pipe(take(1)),
    },
  };
}
